begin;
do $$
declare manager uuid; branch uuid; other_branch uuid; day date:=(now() at time zone 'America/Toronto')::date; first_id uuid; payload jsonb; bad jsonb; before_stock jsonb; actual jsonb; denied boolean; original_role public.user_role; previous_id uuid; old_id uuid;
begin
 select id,location_id,role into manager,branch,original_role from public.profiles where role::text='BRANCH_MANAGER' and status::text='active' and location_id is not null limit 1;
 select id into other_branch from public.locations where id<>branch and is_central is not true limit 1;
 if manager is null or other_branch is null then raise exception 'Need an active branch manager and two branches for rollback tests.'; end if;
 select jsonb_agg(jsonb_build_object('item_id',id,'quantity',0) order by id),jsonb_agg(jsonb_build_object('id',id,'stock',available_stock) order by id) into payload,before_stock from public.catalog_items where is_active is true;
 update public.profiles set role='BRANCH_EMPLOYEE' where id=manager;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',manager,'role','authenticated')::text,true);
 perform set_config('request.jwt.claim.sub',manager::text,true);
 execute 'set local role authenticated';
 if public.inventory_location() is distinct from branch or public.current_location() is not null then raise exception 'Employee scope incorrect'; end if;
 if exists(select 1 from public.catalog_items) or exists(select 1 from public.orders) or exists(select 1 from public.weekly_invoices) then raise exception 'Employee can read manager or central data'; end if;
 actual:=public.branch_inventory_workspace(day);
 previous_id:=(actual->>'expected_previous_count_id')::uuid;old_id:=(actual->>'expected_count_id')::uuid;
 select jsonb_agg(jsonb_build_object('item_id',value->>'id','opening_quantity',(value->>'opening_quantity')::integer,'expected_opening_quantity',(value->>'opening_quantity')::integer,'expected_received_quantity',(value->>'received_quantity')::integer,'used_quantity',0,'wasted_quantity',0,'quantity',(value->>'opening_quantity')::integer+(value->>'received_quantity')::integer)) into payload from jsonb_array_elements(actual->'items');
 first_id:=public.save_branch_inventory_day(day,payload,'Closing count',old_id,previous_id);
 if not exists(select 1 from public.branch_inventory_counts where id=first_id and submitted_by=manager and submitted_at is not null) then raise exception 'Timestamp or author missing'; end if;
 denied:=false;begin perform public.save_branch_inventory_day(day,payload,'Stale',old_id,previous_id);exception when others then denied:=sqlerrm like '%Inventory changed%';end;
 if not denied then raise exception 'Concurrent count was overwritten'; end if;
 bad:=jsonb_set(payload,'{0,used_quantity}','1.5');denied:=false;begin perform public.save_branch_inventory_day(day,bad,'Fractional',first_id,previous_id);exception when others then denied:=sqlerrm like '%whole units%';end;if not denied then raise exception 'Fractional count accepted';end if;
 denied:=false;begin perform public.branch_inventory_workspace(day,other_branch);exception when others then denied:=sqlerrm like '%not accessible%';end;if not denied then raise exception 'Cross-branch workspace accessible';end if;
 denied:=false;begin update public.profiles set role='CENTRAL_ADMIN' where id=manager;exception when others then denied:=sqlerrm like '%Only admin%';end;if not denied then raise exception 'Self-promotion allowed';end if;
 denied:=false;begin update public.branch_inventory_lines set quantity=7 where count_id=first_id;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'History mutable';end if;
 perform public.save_branch_inventory_day(day,payload,'Correction',first_id,previous_id);
 if (select count(*) from public.branch_inventory_counts where location_id=branch and count_date=day)<2 then raise exception 'Correction destroyed history';end if;
 execute 'set local role postgres';
 select jsonb_agg(jsonb_build_object('id',id,'stock',available_stock) order by id) into actual from public.catalog_items where is_active is true;
 if actual is distinct from before_stock then raise exception 'Branch count changed central stock';end if;
 update public.profiles set role=original_role where id=manager;
 execute 'set local role authenticated';
 actual:=public.branch_inventory_workspace(day);
 if actual->'latest'->>'notes' is distinct from 'Correction' then raise exception 'Manager cannot see latest employee count';end if;
 perform public.save_branch_inventory_day(day,payload,'Manager update',(actual->>'expected_count_id')::uuid,previous_id);
 execute 'set local role postgres';
 update public.profiles set role='BRANCH_EMPLOYEE',status='disabled' where id=manager;
 execute 'set local role authenticated';
 denied:=false;begin perform public.branch_inventory_workspace(day);exception when others then denied:=true;end;if not denied then raise exception 'Disabled employee kept access';end if;
 execute 'set local role postgres';
end;$$;
rollback;
select 'Passed: whole-unit counts, immutable corrections, submission timestamps, manager visibility, employee isolation, self-promotion protection, stale-count conflicts and unchanged central stock. All fixtures rolled back.' as result;
